perl -e '
# Read the sequences
my $content = do { local $/; <STDIN> };

# Parse the FASTA
my %sequences;
my $current_name = undef;
my $current_seq = "";

while ($content =~ />([^\n]+)\n([^>]+)/g) {
    my $name = $1;
    my $seq = $2;
    $seq =~ s/\s+//g;
    $sequences{$name} = $seq;
}

my $input_seq = $sequences{"input"};
my $output_seq = $sequences{"output"};

print "Input length: " . length($input_seq) . "\n";
print "Output length: " . length($output_seq) . "\n";

# Find differences
my @diffs;
for my $i (0 .. min(length($input_seq), length($output_seq)) - 1) {
    if (substr($input_seq, $i, 1) ne substr($output_seq, $i, 1)) {
        push @diffs, ($i, substr($input_seq, $i, 1), substr($output_seq, $i, 1));
    }
}

if (length($input_seq) != length($output_seq)) {
    push @diffs, ("length_diff", length($input_seq), length($output_seq));
}

print "Number of differences: " . (scalar(@diffs) / 3) . "\n";
print "\nDifferences:\n";
for (my $i = 0; $i < scalar(@diffs); $i += 3) {
    print "  Position $diffs[$i]: $diffs[$i+1] -> $diffs[$i+2]\n";
}

sub min { return ($_[0] < $_[1]) ? $_[0] : $_[1]; }
' < sequences.fasta

