perl -e '
# Read the sequences
my $content = do { local $/; <STDIN> };

# Parse the FASTA
my %sequences;
while ($content =~ />([^\n]+)\n([^>]+)/g) {
    my $name = $1;
    my $seq = $2;
    $seq =~ s/\s+//g;
    $sequences{$name} = $seq;
}

my $input_seq = $sequences{"input"};
my $output_seq = $sequences{"output"};

my $len_input = length($input_seq);
my $len_output = length($output_seq);

print "Input length: $len_input\n";
print "Output length: $len_output\n";
print "Difference in length: " . ($len_output - $len_input) . "\n\n";

# Find ALL differences
my @diffs;
for my $i (0 .. $len_input - 1) {
    my $in = substr($input_seq, $i, 1);
    my $out = ( $i < $len_output ) ? substr($output_seq, $i, 1) : "";
    if ($in ne $out) {
        push @diffs, [$i, $in, $out];
    }
}

print "Total point mutations: " . scalar(@diffs) . "\n\n";

# Group contiguous mutations
my @groups;
if (@diffs) {
    push @groups, [$diffs[0]];
    for my $i (1 .. $#diffs) {
        my $prev = $diffs[$i-1];
        my $curr = $diffs[$i];
        if ($curr->[0] <= $prev->[0] + 5) {
            push @{$groups[-1]}, $curr;
        } else {
            push @groups, [$curr];
        }
    }
}

print "Groups of mutations (start_pos, end_pos, count):\n";
for my $g (@groups) {
    my $start = $g->[0]->[0];
    my $end = $g->[-1]->[0];
    my $len = $end - $start + 1;
    print sprintf("  Group %d: pos %d to %d (%d bp, %d mutations)\n", 
        int($g->[0]->[0]/100), $start, $end, $len, scalar(@$g));
    for my $d (@$g) {
        print "    pos $d->[0]: $d->[1] -> $d->[2]\n";
    }
}
