    if (substr($input_seq, $i, 1) eq substr($output_seq, $o, 1)) {
        $i++;
        $o++;
    } else {
        # Check if we are in an insertion region
        # Look ahead in output to find a matching sequence
        my $found_insert = 0;
        for my $lookahead (1..50) {
            if ($o + $lookahead < $output_len && $i < $input_len && 
                substr($input_seq, $i, 1) eq substr($output_seq, $o + $lookahead, 1)) {
