my $o = 0;

while ($i < $input_len && $o < $output_len) {
    if (substr($input_seq, $i, 1) eq substr($output_seq, $o, 1)) {
        $i++;
        $o++;
    } else {
        # Found a difference, determine if insertion or substitution
        my $insertion_len = 0;

        # Check if this is an insertion in output
        for my $look (1..50) {
            if ($o + $look < $output_len && $i < $input_len &&
                substr($output_seq, $o + $look, 1) eq substr($input_seq, $i, 1)) {
